/*
 * A040935  Continued fraction for sqrt(967).
 * https://oeis.org/A040935
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, cofr, easy
 * Formula:   not stated
 * Range:     u8 n <= 1, u16 n <= 84, u32 n <= 84, u64 n <= 84, u128 n <= 84,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/*  OEIS A040935 – Continued fraction for sqrt(967)
 *
 *  The n-th term a(n) is the n-th partial quotient of the simple continued
 *  fraction expansion of √967.  It is generated by the standard algorithm:
 *
 *      a0 = floor(√D)
 *      m0 = 0, d0 = 1, a0 = floor(√D)
 *      ai+1 = (a0 + mi) / di
 *      mi+1 = di*ai+1 - mi
 *      di+1 = (D - mi+1^2) / di
 *
 *  D = 967.  The sequence repeats with period 15 after the initial term.
 *  This implementation performs at most n iterations of the update
 *  equations, which is fast enough for all values required by the tests
 *  (n up to about 10 000).
 */

#include <stddef.h>
#include <stdint.h>

seq_t a(idx_t n)
{
    const seq_t D = 967;    /* the square‑free radicand */
    seq_t m = 0;
    seq_t d = 1;
    seq_t a0 = 31;          /* floor(sqrt(D)) */

    seq_t a_cur = a0;       /* a(0) */
    if (n == 0)
        return a_cur;

    for (idx_t i = 1; i <= n; ++i) {
        /* m_{i} = d_{i-1} * a_{i-1} - m_{i-1} */
        m = d * a_cur - m;
        /* d_{i} = (D - m_{i}^2) / d_{i-1} */
        d = (D - m * m) / d;
        /* a_{i} = (a0 + m_{i}) / d_{i} */
        a_cur = (a0 + m) / d;
    }
    return a_cur;
}
